/* Connection presentation for the synthetic setup wizard. */
const prototypeProviders={
 codex_cli:{name:'Codex CLI',method:'Official account session',destination:'OpenAI through the isolated Codex runner',cli:true},
 openai:{name:'OpenAI API',method:'Provider API key',destination:'OpenAI API',cli:false},
 claude_cli:{name:'Claude Code',method:'Official account session',destination:'Anthropic through the isolated Claude runner',cli:true},
 anthropic:{name:'Anthropic API',method:'Provider API key',destination:'Anthropic API',cli:false},
 google:{name:'Google API',method:'Provider API key',destination:'Google API',cli:false},
 local:{name:'Compatible endpoint',method:'Approved endpoint and credential',destination:'Your explicitly authorized endpoint',cli:false}
};
function prototypeProvider(){return prototypeProviders[state.provider]||prototypeProviders.codex_cli;}
function providerConnectionForm(){const provider=prototypeProvider();return `<h2>Connect a model provider</h2><p>Choose how the agents access a model. Repository access is configured separately in the next project step.</p><label class="field">Model provider<select id="provider-choice">${Object.entries(prototypeProviders).map(([id,p])=>`<option value="${id}" ${state.provider===id?'selected':''}>${p.name} · ${p.cli?'account session':'API key'}</option>`).join('')}</select></label><div class="connection-method"><div class="eyebrow">AUTHENTICATION METHOD</div><strong>${provider.method}</strong><p>${provider.cli?'Sign in with the official CLI in your own terminal. The factory keeps a dedicated session, separate from your everyday CLI.':'Configure a write-only credential for this destination. Credential values never appear in configuration exports.'}</p><div class="status-line">${tag('Illustrative connection','amber')}<span class="muted">No authentication is performed by this mockup.</span></div></div><div class="notice">Context destination: ${provider.destination}.<br>${provider.cli?'CLI subscription limits and charges are managed by the provider.':'API usage has a separately authorized spending budget.'}</div><button class="primary" data-next="1">Continue to model</button>`;}
function githubConnectionForm(){return `<h2>Connect a GitHub project</h2><p>GitHub supplies repository access and draft PR delivery. It is independent of your model provider.</p><div class="connection-method"><div class="section-head"><strong>GitHub connection</strong>${tag('Example only')}</div><dl class="kv"><dt>Available method</dt><dd>Scoped access token · write-only credential</dd><dt>Destination</dt><dd>GitHub API</dd><dt>Access scope</dt><dd>Selected repositories only</dd></dl><a class="button-link" href="#tools">Manage GitHub connection</a><p class="footer-note">The current factory stores read and publish credentials separately. A GitHub App installation flow is a future integration, not a working button in this prototype.</p></div><label class="field">Repository<input value="https://github.com/example/checkout-service" readonly><small>Synthetic example repository.</small></label><ul class="checklist"><li>Read source ${tag('Example: configured','green')}</li><li>Create branch and draft PR ${tag('Example: configured','green')}</li><li>Create repositories ${tag('Not authorized')}</li><li>Merge, deploy or release ${tag('Not authorized')}</li></ul><button class="primary" data-next="3" style="margin-top:20px">Check readiness</button>`;}
